import os,sys
sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from lib import REPO,OUTDIR,ARGS
SRC_CSV=(os.path.join(REPO,'research','activity','sources_task19.csv') if ARGS.write else OUTDIR+'sources_task19.csv')
import csv
H=['source_id','short_cite','full_citation','url','doi','year','type','rank','access','licence','notes']
R=[
['S0800','OWID electricity production by source','Our World in Data (accessed 22 Oct 2026). Electricity production by source, World and countries, 1900-2025 (grapher electricity-production-by-source). Compiled from Ember Yearly Electricity Data (2026), Energy Institute Statistical Review of World Energy (2026), Pinto et al. (2023) for the world before 1965, and DESNZ UK electricity by fuel 1920-2020.','https://ourworldindata.org/grapher/electricity-production-by-source','',2026,'compilation',2,'open','open','DOWNLOADED (CSV, 10,124 rows). World 1900-2025; countries 1965/1985-2025; UK from 1920. Coal, gas, oil, nuclear, hydro, solar, wind, bioenergy, other renewables in TWh. CC BY licence on OWID processing; underlying EI data carries EI copyright. Pre-1965 world split between fuels is a reconstruction, not statistics.'],
['S0801','Pinto et al. 2023 (Energy 269)','Pinto, R., Henriques, S.T., Brockway, P.E., Heun, M.K. and Sousa, T. (2023). The rise and stall of world electricity efficiency: 1900-2017, results and insights for the renewables transition. Energy 269: 126775.','https://doi.org/10.1016/j.energy.2023.126775','10.1016/j.energy.2023.126775',2023,'peer_reviewed',3,'open','open','Open access (CC BY); accompanying preprint MPRA 112541 read for method and efficiency statements. Provides the 1900-2017 world electricity-by-fuel series OWID uses before 1965 (supplementary data not downloaded directly; used via S0800). Figure 10 shows fossil-electricity efficiency but gives no numbers.'],
['S0802','Ember Yearly Electricity Data 2026','Ember (2026). Yearly Electricity Data (full release, long format), generation, capacity, demand and emissions for over 200 geographies, 2000-2025.','https://ember-energy.org/data/yearly-electricity-data/','',2026,'compilation',2,'open','open','DOWNLOADED (files.ember-energy.org/public-downloads/yearly_full_release_long_format.csv, 49 MB). Used to confirm the OWID series for 2000 onward (OWID redistributes it); not read separately row by row. CC BY 4.0.'],
['S0803','Energy Institute Statistical Review 2026','Energy Institute (2026). Statistical Review of World Energy, 75th edition (consolidated dataset).','https://www.energyinst.org/statistical-review','',2026,'compilation',2,'inaccessible','restricted','Direct download returned HTTP 403 (www.energyinst.org and the excel_doc URL); data were consumed only through Our World in Data (S0800, S0805, S0806). Steve can download the consolidated dataset to check the 1965-2025 country series.'],
['S0804','EIA International Energy Statistics (bulk)','U.S. Energy Information Administration (accessed 22 Oct 2026). International Energy Statistics, bulk file INTL.zip (annual series, 1980-2025): coal, oil, gas production and consumption in physical units; electricity generation and capacity by fuel; plus Monthly Energy Review Tables 2.6, 4.3, 6.2, 7.2a and Petroleum well-completion tables E_ERTW*.','https://www.eia.gov/opendata/bulk/INTL.zip','',2026,'agency',4,'open','open','DOWNLOADED (24 MB zip, 100,459 annual series). Public domain. Coverage mostly 1980 onward; EIA world oil totals for 1973-1979 are incomplete (50 Mb/d in 1973), so physical volumes are used from 1980. Coal tonnes in 1980-1984 are not used because the implied energy/tonne ratio jumps (6.2 vs 5.5 MWh/t). US MER tables from https://www.eia.gov/totalenergy/data/browser/csv.php?tbl=T06.02 (and T02.06, T04.03, T07.02A); wells from https://www.eia.gov/dnav/pet/hist_xls/E_ERTW0_XWC0_NUS_Ca.xls (1949-2010, series discontinued).'],
['S0805','OWID energy dataset','Our World in Data (accessed 22 Oct 2026). Energy dataset (owid-energy-data.csv): primary energy, production and consumption by fuel, electricity, 1900-2025, from the Energy Institute Statistical Review, EIA and Ember.','https://raw.githubusercontent.com/owid/energy-data/master/owid-energy-data.csv','',2026,'compilation',2,'open','open','DOWNLOADED (9 MB). Used for coal, oil and gas consumption in TWh (1965 onward). CC BY.'],
['S0806','OWID oil and gas production (long run)','Our World in Data (accessed 22 Oct 2026). Oil production by country and Gas production by country (TWh), 1900-2025; Etemad and Luciani (1991) World Energy Production 1800-1985 for 1900-1979, Energy Institute Statistical Review from 1965, EIA for gaps.','https://ourworldindata.org/grapher/oil-production-by-country','',2026,'compilation',2,'open','open','DOWNLOADED (oil-production-by-country.csv, gas-production-by-country.csv). Energy units only; tonnes and m3 are modelled from them (see notes). Etemad and Luciani (book) not read directly. Same pattern as the coal series S0230.'],
['S0807','OWID Minerals explorer (USGS/BGS)','Our World in Data (accessed 22 Oct 2026). Minerals explorer: production of minerals by country, 1900-2024, built from USGS Mineral Commodity Summaries (2025), USGS Historical Statistics for Mineral and Material Commodities (DS140, 2024 release) and BGS World Mineral Statistics (2025). Downloaded per commodity and type via explorers/minerals.csv.','https://ourworldindata.org/explorers/minerals','',2026,'compilation',2,'open','open','DOWNLOADED (30 commodity-type files). Stand-in for the unreachable USGS DS140 files (usgs.gov returned 403; S3 403). World totals missing for lead and zinc refinery, tin smelter; tellurium and indium absent. Where USGS and BGS overlap OWID prefers USGS and drops BGS if world totals differ by more than 10%. CC BY on OWID processing; underlying USGS data public domain, BGS data open government licence.'],
['S0808','USGS Mineral Commodity Summaries 2026','U.S. Geological Survey (2026). Mineral Commodity Summaries 2026. Reston, VA. Earlier editions 2020, 2022, 2024 and 2025 also read for tellurium and indium.','https://pubs.usgs.gov/periodicals/mcs2026/mcs2026.pdf','',2026,'agency',4,'open','open','DOWNLOADED (also mcs2020, mcs2022, mcs2024, mcs2025 at the same pattern). World refinery production of indium and tellurium 2018-2025e and 2025e world totals for copper, aluminium, silver, zinc, lead, tin, nickel, cadmium, molybdenum, rare earths and cement read by text extraction; values are rounded and some country entries are withheld. Editions earlier than 2020 use a different URL pattern (404).'],
['S0810','IRENA Electricity Statistics 2026 H2','International Renewable Energy Agency (2026). Electricity statistics by country/area, technology, data type, grid connection and year (PxWeb table Country_ELECSTAT_2026_H2_PX), updated 2026-09-28. Capacity (MW) and generation (GWh), 2000-2025.','https://pxweb.irena.org/pxweb/en/IRENASTAT/Power%20Capacity%20and%20Generation/Country_ELECSTAT_2026_H2_PX.px','',2026,'agency',4,'open','unknown','DOWNLOADED via the open PxWeb API (POST, one technology per request). Onshore/offshore wind, PV, CSP, hydro, bioenergy, peat, geothermal, nuclear, coal, gas, oil, by country. No World row, so world = sum of countries. Capacity values for 2025 are IRENA estimates. No licence statement checked.'],
['S0818','IAEA TECDOC-1975 (2021)','IAEA (2021). Spent Fuel Performance Assessment and Research: Final Report of a Coordinated Research Project (SPAR-IV). IAEA-TECDOC-1975, Vienna.','https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1975web.pdf','',2021,'agency',4,'open','restricted','READ (foreword and burnup passages). States that by the end of 2020 over 400,000 tHM of spent fuel had been discharged and that spent fuel is accumulating at about 7,000 tHM per year; German PWR discharge burnup rose from 35 GWd/tHM (1983) to 50 (1998) and 65 now. Used only as validation for modelled discharge.'],
['S0819','IPCC AR5 WGIII Annex III','Schlomer, S., Bruckner, T., Fulton, L. et al. (2014). Annex III: Technology-specific cost and performance parameters. In: Climate Change 2014: Mitigation of Climate Change, Contribution of Working Group III to AR5, IPCC. Table A.III.1.','https://www.ipcc.ch/site/assets/uploads/2018/02/ipcc_wg3_ar5_annex-iii.pdf','10.1017/CBO9781107415416.025',2014,'peer_reviewed',3,'open','open','DOWNLOADED and read (pp. 1329-1356). Plant lifetime (yr) and full-load-hours ranges (min/max) by technology; USD2010. One vintage only (about 2010).'],
['S0820','Fraunhofer ISE Photovoltaics Report 2026','Fraunhofer Institute for Solar Energy Systems ISE (14 July 2026). Photovoltaics Report (with PSE Projects GmbH), Freiburg.','https://www.ise.fraunhofer.de/content/dam/ise/de/documents/publications/studies/Photovoltaics-Report.pdf','',2026,'grey',5,'open','unknown','DOWNLOADED. Production by technology is chart-only except the 2025 figures: thin film 16 GWp, mono-Si 690 GWp, total 706 GWp (ITRPV); c-Si about 98%. Technology time series (1980-2025) not extractable from the text layer; the charts need manual reading by Steve or a request to Fraunhofer ISE.'],
]
with open(SRC_CSV,'w',newline='',encoding='utf-8') as f:
    w=csv.writer(f,lineterminator='\n'); w.writerow(H); w.writerows(R)
